  'troubleshooting.portal.result': '{status} heißt: Netz und Zertifikat sind in Ordnung. Bei einem SSL- oder Vertrauensfehler passt der Hostname nicht zum Zertifikat, oder die eigene CA fehlt unter „Lokaler Computer → Vertrauenswürdige Stammzertifizierungsstellen“. Eine CA nur im Benutzerspeicher reicht nicht, der Dienst nutzt den Speicher des Computers.',
  'troubleshooting.reports.result': '{at} ist der Zeitpunkt in UTC, {version} die Agentversion. Der Worker meldet alle 30 Sekunden. Liegt {at} deutlich zurück, steht der Grund im Log in Zeilen mit {heartbeat} oder {channel}. Strg+C beendet die Live-Ansicht. Aufträge als SYSTEM protokolliert der Broker in {log}.',
  'troubleshooting.repair.result': 'Starte die aktuelle EXE aus dem Downloadordner, nicht aus {path}. Reparieren behält Geräte-ID und Modus. Die neue Registrierungsdatei erstellst du unter {add}, ihren Namen setzt du im Befehl ein. Die Installation gilt erst als erfolgreich, wenn der Agent innerhalb von drei Minuten eine Meldung abgibt, sonst stellt sie den vorherigen Stand wieder her.',
  'troubleshooting.cache.text': 'Der Agent entpackt gebündelte Bibliotheken nach {runtime} und {workerRuntime}. Der Befehl stoppt den Agent, leert nur diese beiden Ordner und startet ihn wieder. Beim Start werden sie neu erstellt. Solange eine Installation oder ein Update läuft, bricht er ab.',
  'troubleshooting.cache.warning': 'Lösche sonst nichts unter {path}. {config} und {worker} enthalten die Registrierung, {current} und {previous} die installierte und die Rollback-Version, {updates} und {transfers} laufende Updates und Übertragungen.',
  'troubleshooting.silent.noneHint': 'Verbinde dein erstes Gerät unter {add}.',
  'troubleshooting.silent.allReport': {one: 'Das Gerät hat in den letzten zwei Minuten gemeldet.', other: 'Alle {count} Geräte haben in den letzten zwei Minuten gemeldet.'},
  'troubleshooting.silent.lastReport': 'Letzte Meldung: {time}',

