  'assistantSettings.organization.text': 'Mit diesem Schlüssel kann jede Person, die ein Gerät sehen darf, den KI-Assistenten dazu fragen. Erstelle bei deinem KI-Anbieter einen API-Schlüssel und trage ihn hier ein. Fragen mit diesem Schlüssel rechnet der Anbieter über dieses Konto ab. Schlüssel für einzelne Kunden legst du unten fest, und jede Person kann unter „Mein Konto“ einen eigenen Schlüssel hinterlegen.',
  'assistantSettings.personal.title': 'KI-Assistent',
  'assistantSettings.personal.text': 'Der KI-Assistent beantwortet Fragen zu deinen Geräten und hilft dir bei der Fehlersuche. Erstelle bei deinem KI-Anbieter einen API-Schlüssel und trage ihn hier ein. Dieser Schlüssel gilt nur für deine eigenen Fragen. Ein Owner kann in den Einstellungen Schlüssel für das ganze Portal oder für einzelne Kunden hinterlegen.',
