  'help.assistant.title': 'Assistent',
  'help.assistant.tip1': 'Der Assistent antwortet aus den Daten, die Nodiverna zum Gerät speichert, zum Beispiel Inventar, Messwerte, Ereignisse und Aufträge.',
  'help.assistant.tip2': 'Die Zeile unter dem Fragefeld zeigt, welcher API-Schlüssel deine Frage beantwortet. Ein Owner hinterlegt Schlüssel für das Portal und für Kunden unter Einstellungen › KI-Assistent, und deinen eigenen Schlüssel kannst du unter „Mein Konto“ hinterlegen.',
  'help.assistant.tip3': 'Der Assistent kann Befehle vorschlagen, zum Beispiel einen Dienst neu zu starten oder den Grafiktreiber zu aktualisieren. Ein Befehl läuft erst, wenn du „Auf Gerät ausführen“ wählst, mit deinen Berechtigungen und mit MFA, wenn die Aktion sie braucht.',
