  'help.entra.title': 'Microsoft Entra ID',
  'help.entra.tip1': 'Gib die Mandanten-ID, die Client-ID und einen Schlüssel oder ein Zertifikat ein. Wähle „Verbindung testen“, um sie zu prüfen.',
