  'help.entra.tip3': 'Gruppenzuordnungen geben Rollen bei jeder Anmeldung. Entfernst du eine Person aus der Gruppe, entzieht Nodiverna ihr die Rolle und beendet ihre Sitzungen innerhalb von 15 Minuten.',
