  'pluginAd.signIn.bodyDomain': 'Änderungen, die du über eine Erweiterung machst, laufen mit deinem AD-Konto, deshalb wendet der Server deine AD-Rechte an und protokolliert deinen Namen. Eine Anmeldung gilt für alle Server in {domain}. Sie endet, wenn du dich bei Nodiverna abmeldest, spätestens nach 8 Stunden.',
  'pluginAd.signIn.bodyLocal': '{device} ist in keiner AD-Domäne, deshalb laufen Änderungen, die du über eine Erweiterung machst, mit einem lokalen Windows-Konto dieses Servers. Der Server wendet die Rechte dieses Kontos an und protokolliert seinen Namen. Die Anmeldung gilt nur für diesen Server und endet, wenn du dich bei Nodiverna abmeldest, spätestens nach 8 Stunden.',
